def countCompleteComponents(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    nodes = [0] * n
    links = [0] * n
    for i in range(n):
        nodes[find(i)] += 1
    for a, b in edges:
        links[find(a)] += 1
    return sum(1 for i in range(n) if nodes[i] and links[i] == nodes[i] * (nodes[i] - 1) // 2)
